void Solver::bump_var(int var, double coeff) {
    // Apply a non-linear bump: use a slightly amplified increment for high-activity variables
    // to create stronger differentiation and help escape local optima
    double inc = var_inc * coeff;
    // Boost variables that are already highly active (positive feedback for "hot" variables)
    double cur = activity[var];
    if (cur > 0 && cur > var_inc * 0.1) {
        inc *= 1.05;
    }
    activity[var] += inc;
    if (activity[var] > 1e100) {
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
